const canvas = document.querySelector('#game');
const ctx = canvas.getContext('2d', { alpha: false });
const $ = (s) => document.querySelector(s);
const ui = {
  title: $('#titleScreen'), begin: $('#beginBtn'), continue: $('#continueBtn'),
  hud: $('#hud'), chapterNum: $('#chapterNum'), chapterName: $('#chapterName'),
  objective: $('#objective'), objectiveText: $('#objectiveText'), wonderCount: $('#wonderCount'),
  wonderTotal: $('#wonderTotal'), wonderHud: $('#wonderHud'), pauseBtn: $('#pauseBtn'),
  interact: $('#interactBtn'), interactLabel: $('#interactLabel'), walkHint: $('#walkHint'),
  dialogue: $('#dialogue'), speaker: $('#speaker'), line: $('#line'), choices: $('#choices'),
  advance: $('#advance'), location: $('#location'), locationName: $('#locationName'),
  locationSub: $('#locationSub'), chapterCard: $('#chapterCard'), ccKicker: $('#ccKicker'),
  ccNum: $('#ccNum'), ccTitle: $('#ccTitle'), ccSub: $('#ccSub'), pause: $('#pauseScreen'),
  resume: $('#resumeBtn'), sound: $('#soundBtn'), restart: $('#restartBtn'), quit: $('#quitBtn'),
  end: $('#endScreen'), endKicker: $('#endKicker'), endCopy: $('#endCopy'), endWonders: $('#endWonders'),
  endTime: $('#endTime'), again: $('#againBtn'), endTitle: $('#endTitleBtn'), fade: $('#fade'),
  toast: $('#toast'), rotate: $('#rotateHint'), stickZone: $('#stickZone'), stickBase: $('#stickBase'),
  stickNub: $('#stickNub'),
};

const CHAPTERS = [
  { roman:'I', name:'The Long Field', sub:'autumn — the year the sky came down', place:'The Long Field', placeSub:'the edge of the map', sky:['#283d5d','#f2a66f','#e6a764'], ground:'#62533e', far:'#59616a', hills:'#526052' },
  { roman:'II', name:'The Listening Woods', sub:'later — where the trees remember', place:'The Listening Woods', placeSub:'somewhere the map forgot', sky:['#172a43','#bc7970','#e8a878'], ground:'#394537', far:'#334338', hills:'#304336' },
  { roman:'III', name:'The Sea Above', sub:'at the very top of the world', place:'The Sea Above', placeSub:'a little higher than yesterday', sky:['#111b3b','#857ab0','#e8b88b'], ground:'#5b516b', far:'#56536e', hills:'#514665' },
];
const WORLD_CHAPTER = 2500;
const WORLD_END = WORLD_CHAPTER * 3;
const player = { x:110, y:0, facing:1, walk:0, bob:0, speed:0, lastX:110 };
const camera = { x:0, y:0, look:0 };
const game = {
  mode:'title', chapter:0, startedAt:0, elapsed:0, lastTime:0, time:0,
  wonders:0, found:new Set(), dialogue:null, currentZone:null, stage:0,
  choiceMemory:'', paused:false, muted:false, sound:null, audioCtx:null,
  storyStep:0, activeZone:null, seenLocation:-1, saveKey:'lantern-skywhale-save-v1',
  particles:[], fireflies:[], titleElapsed:0, ending:false,
};
let W=0,H=0,DPR=1, scale=1, horizon=0, floorY=0;
const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

function resize(){
  DPR=Math.min(devicePixelRatio||1,2); W=innerWidth; H=innerHeight;
  canvas.width=Math.round(W*DPR); canvas.height=Math.round(H*DPR);
  canvas.style.width=W+'px'; canvas.style.height=H+'px';
  ctx.setTransform(DPR,0,0,DPR,0,0);
  scale=Math.max(.72,Math.min(1.25,H/800));
  horizon=H*.49; floorY=H*.80;
}
window.addEventListener('resize',resize,{passive:true}); resize();

function hash(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)}
function lerp(a,b,t){return a+(b-a)*t}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function ease(t){return t*t*(3-2*t)}
function chapterOf(x){return clamp(Math.floor(x/WORLD_CHAPTER),0,2)}
function localX(x){return x%WORLD_CHAPTER}
function hexA(hex,a=1){const n=parseInt(hex.slice(1),16);return `rgba(${n>>16},${n>>8&255},${n&255},${a})`}
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function setBar(on){document.documentElement.style.setProperty('--bar',on?'clamp(28px,6vh,62px)':'0px')}

// Sound is generated locally: no downloads or autoplay; begins after the player's first gesture.
function sound(type='soft'){
  if(game.muted)return;
  try{
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!game.audioCtx)game.audioCtx=new AC();
    const a=game.audioCtx;if(a.state==='suspended')a.resume();
    const now=a.currentTime, osc=a.createOscillator(), gain=a.createGain();
    osc.type=type==='chime'?'sine':'triangle';
    const notes=type==='chime'?[660,990,1320]:type==='step'?[120]:[330,440];
    osc.frequency.setValueAtTime(notes[0],now);
    if(type==='chime')osc.frequency.exponentialRampToValueAtTime(notes[2],now+.35);
    gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(type==='step'?.035:.045,now+.03);
    gain.gain.exponentialRampToValueAtTime(.0001,now+(type==='step'?.12:.65));
    osc.connect(gain);gain.connect(a.destination);osc.start(now);osc.stop(now+(type==='step'?.14:.7));
  }catch{}
}
function showToast(text){ui.toast.innerHTML=text;ui.toast.classList.add('is-on');setTimeout(()=>ui.toast.classList.remove('is-on'),2100)}
function save(){try{localStorage.setItem(game.saveKey,JSON.stringify({x:player.x,wonders:[...game.found],chapter:game.chapter,stage:game.storyStep}))}catch{}}
function loadSave(){try{return JSON.parse(localStorage.getItem(game.saveKey)||'null')}catch{return null}}

const wonders = [
  {x:330,y:.68,name:'A field mouse’s hat',desc:'A tiny hat, left for a tiny head.'},
  {x:730,y:.57,name:'A blue feather',desc:'It feels warm. Feathers usually do.'},
  {x:1110,y:.66,name:'A wishing seed',desc:'The wind is carrying its wish somewhere.'},
  {x:1740,y:.55,name:'A moon snail',desc:'It leaves a little silver wherever it goes.'},
  {x:2730,y:.63,name:'A pocket of birdsong',desc:'The woods have been keeping it safe.'},
  {x:3260,y:.53,name:'A fox’s red button',desc:'Perhaps it fell from a very small coat.'},
  {x:4160,y:.68,name:'A raindrop that forgot to fall',desc:'There is a whole sky inside it.'},
  {x:5260,y:.57,name:'A star’s old address',desc:'No street. Just “up, then left.”'},
  {x:6650,y:.50,name:'A piece of almost-morning',desc:'It glows like the first thing you remember.'},
];
ui.wonderTotal.textContent=wonders.length;

// Story beats live at landmarks. Moving into range reveals the small lantern prompt.
const zones = [
  {x:190,chapter:0,label:'Listen',kind:'opening'},
  {x:560,chapter:0,label:'Say hello',kind:'moth'},
  {x:1280,chapter:0,label:'Look closer',kind:'well'},
  {x:2220,chapter:0,label:'Follow the light',kind:'gate'},
  {x:2640,chapter:1,label:'Listen',kind:'woods'},
  {x:3150,chapter:1,label:'Say hello',kind:'fox'},
  {x:4280,chapter:1,label:'Look closer',kind:'tree'},
  {x:4740,chapter:1,label:'Climb aboard',kind:'whale'},
  {x:5140,chapter:2,label:'Listen',kind:'sky'},
  {x:6100,chapter:2,label:'Make a wish',kind:'star'},
  {x:7100,chapter:2,label:'Go home',kind:'ending'},
];

function linesFor(kind){
  const name=game.choiceMemory;
  const content={
    opening:[['','There was a time when the sky sat so low, you could hear the stars bump their heads.'],['Mara','Grandma says if I find the one that fell, I can ask it anything.'],['','So Mara took her little lantern and went to look.']],
    moth:[['Mara','Hello? Are you a firefly?'],['Pip','I am a moth. Fireflies are very showy.'],['Mara','I’m looking for a fallen star.'],['Pip','Then you’ll need someone who knows the dark. I know it very well.']],
    well:[['','At the bottom of the old well, a voice was humming the tune Mara’s mother used to hum.'],['Mara','Do you know where the star went?'],['Well','Down is just up, if you wait long enough.']],
    gate:[['Pip','The woods begin past this fence. I could come with you.'],['Mara','Would you?'],['Pip','I thought you’d never ask.']],
    woods:[['','The trees leaned in. They had been waiting a long time to tell somebody something.'],['Mara','What are you all whispering about?'],['Trees','That the moon misses the sea. That the sea misses the moon. That you are very small.'],['Mara','I know.']],
    fox:[['Mara','You’re wearing a red button.'],['Fox','I found it. I’m a fox. We find things.'],['Fox','My name is Rowan. The sky whale said you’d come.'],['Mara','There’s a sky whale?']],
    tree:[['','The oldest tree held a thousand years of quiet in its roots.'],['Tree','The star is not lost, little one. It is lonely.'],['Mara','Can lonely things be found?'],['Tree','Only by other lonely things.']],
    whale:[['','Something immense moved above the treetops. The night rippled like water.'],['Whale','I have carried the moon for a hundred years. I have never carried a child.'],['Mara','I’m not very heavy.'],['Whale','That is not what worries me.']],
    sky:[['','They climbed higher than the birds, higher than the weather, higher than the last thing Mara was sure of.'],['Mara','I can see my house. It’s so small.'],['Pip','It’s exactly the right size for you.']],
    star:[['','The fallen star was no bigger than a plum. It had been trying very hard not to cry.'],['Star','I can’t remember how to get home.'],['Mara','That’s alright. I don’t always remember either.'],['Star','Will you show me?']],
    ending:[['','Mara walked the star back to the place where the sky met the sea.'],['Whale','What did you wish for, little one?'],['Mara',name==='company'?'That nobody has to be lonely on the way home.':name==='wonder'?'That I never stop noticing the small things.':'I haven’t decided yet.'],['','The star went up. The sky rose a little higher. And the world had room for all of them.']],
  };
  return content[kind]||[];
}

// Painterly side-scrolling world: every landscape is drawn from layered gradients and hand-built silhouettes.
export function paint(ctx, state){
  const {w,h,dpr,time,camera,player,chapter,chapters,wonders,found,mode}=state;
  const ch=chapters[chapter], horizon=h*.49, ground=h*.80, s=Math.max(.72,Math.min(1.25,h/800));
  const night=chapter===2;
  const sky=ctx.createLinearGradient(0,0,0,horizon*1.65);
  sky.addColorStop(0,night?'#101b38':chapter===1?'#182b42':'#263b5b');
  sky.addColorStop(.58,ch.sky[0]);sky.addColorStop(.83,ch.sky[1]);sky.addColorStop(1,ch.sky[2]);
  ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
  // The sky's last light, held close to the horizon.
  const glow=ctx.createRadialGradient(w*.69,horizon*.93,2,w*.69,horizon*.93,h*.67);
  glow.addColorStop(0,night?'rgba(246,192,156,.21)':'rgba(255,209,156,.34)');
  glow.addColorStop(.28,night?'rgba(180,157,216,.11)':'rgba(255,182,135,.15)');glow.addColorStop(1,'rgba(255,170,130,0)');
  ctx.fillStyle=glow;ctx.fillRect(0,0,w,horizon*1.8);
  if(night)drawStars(ctx,w,h,time,camera.x);
  drawSun(ctx,w,h,time,night);
  drawClouds(ctx,w,h,time,camera.x,chapter);
  drawRidge(ctx,w,h,time,camera.x,chapter,0.07,chapter===2?'#393a5b':'#6d6870',.76);
  drawRidge(ctx,w,h,time,camera.x,chapter,0.13,ch.far,.86);
  drawPines(ctx,w,h,time,camera.x,chapter);
  // distant haze at the horizon
  const haze=ctx.createLinearGradient(0,horizon*.76,0,horizon*1.16);
  haze.addColorStop(0,'rgba(241,183,146,0)');haze.addColorStop(.62,chapter===2?'rgba(166,170,209,.17)':'rgba(244,194,157,.20)');haze.addColorStop(1,'rgba(244,194,157,0)');
  ctx.fillStyle=haze;ctx.fillRect(0,horizon*.72,w,horizon*.48);
  drawLand(ctx,w,h,time,camera.x,chapter,ground);
  drawPath(ctx,w,h,time,camera.x,chapter,ground);
  drawLandmarks(ctx,w,h,time,camera.x,chapter,ground);
  drawFlowers(ctx,w,h,time,camera.x,chapter,ground);
  drawWonders(ctx,w,h,time,camera.x,chapter,wonders,found,ground);
  if(player.visible!==false)drawPlayer(ctx,w,h,time,camera.x,player,ground,mode);
  drawFireflies(ctx,w,h,time,camera.x,chapter);
  // foreground grass blades lend depth and gentle motion
  drawForeground(ctx,w,h,time,camera.x,chapter,ground);
  // subtle warm bloom centered on the little lantern
  if(player.visible!==false&&mode==='playing'){
    const px=player.screenX, py=ground-55*s;
    const lantern=ctx.createRadialGradient(px,py,1,px,py,95*s);
    lantern.addColorStop(0,'rgba(255,216,143,.16)');lantern.addColorStop(.42,'rgba(255,200,125,.055)');lantern.addColorStop(1,'rgba(255,200,125,0)');
    ctx.fillStyle=lantern;ctx.fillRect(px-100*s,py-100*s,200*s,200*s);
  }
  drawEdgeShade(ctx,w,h);
}
function drawStars(c,w,h,t,cam){
  c.save();
  for(let i=0;i<115;i++){
    const x=(hash(i*9+2)*w+Math.sin(t*.015+i)*5-(cam*.012)%w+w)%w;
    const y=hash(i*19+5)*h*.55;const tw=.35+.65*(.5+.5*Math.sin(t*.0016+i*7));
    c.globalAlpha=tw*(.45+hash(i+6)*.5);c.fillStyle=i%13===0?'#ffe9c1':'#dbe1fa';
    c.beginPath();c.arc(x,y,(i%17===0?1.4:.6)+hash(i)*.8,0,Math.PI*2);c.fill();
  }
  // A pale, distant river of stars.
  c.globalAlpha=.12;
  const milky=c.createLinearGradient(w*.22,0,w*.84,h*.58);
  milky.addColorStop(0,'rgba(205,211,255,0)');milky.addColorStop(.48,'rgba(219,219,255,.55)');milky.addColorStop(1,'rgba(205,211,255,0)');
  c.fillStyle=milky;c.save();c.translate(w*.5,h*.25);c.rotate(-.43);c.fillRect(-w*.5,-25,w,50);c.restore();
  c.restore();
}
function drawSun(c,w,h,t,night){
  const x=w*.70,y=h*.265+(night?0:Math.sin(t*.00008)*4),r=Math.min(w,h)*(night?.043:.052);
  const halo=c.createRadialGradient(x,y,r*.2,x,y,r*3.4);
  halo.addColorStop(0,night?'rgba(240,226,206,.23)':'rgba(255,215,164,.28)');halo.addColorStop(1,'rgba(255,215,164,0)');
  c.fillStyle=halo;c.beginPath();c.arc(x,y,r*3.4,0,Math.PI*2);c.fill();
  c.beginPath();c.arc(x,y,r,0,Math.PI*2);
  c.fillStyle=night?'#e4dcca':'#f6d5aa';c.globalAlpha=.83;c.fill();c.globalAlpha=1;
  if(night){c.beginPath();c.arc(x+r*.34,y-r*.05,r*.87,0,Math.PI*2);c.fillStyle='#192342';c.fill()}
}
function drawClouds(c,w,h,t,cam,chapter){
  for(let i=0;i<7;i++){
    const speed=(i%2?.003:.006),x=((i*267+cam*speed+t*speed*9)%(w+360))-180;
    const y=h*(.12+hash(i+4)*.26),width=(100+hash(i+9)*170)*(h/800);
    c.globalAlpha=.10+hash(i+5)*.11;c.fillStyle=chapter===2?'#d9d4ed':'#f4d8c0';
    c.beginPath();c.ellipse(x,y,width*.5,11*(h/800),0,0,Math.PI*2);c.ellipse(x-width*.12,y-5,width*.27,12*(h/800),0,0,Math.PI*2);c.ellipse(x+width*.16,y-2,width*.31,9*(h/800),0,0,Math.PI*2);c.fill();
  }
  c.globalAlpha=1;
}
function drawRidge(c,w,h,t,cam,chapter,depth,color,base){
  const y=h*base, step=w/5;
  c.beginPath();c.moveTo(0,h);
  for(let i=-1;i<7;i++){
    const x=i*step-(cam*depth%step), peak=y-h*(.06+hash(i+chapter*31+depth*10)*.13);
    c.lineTo(x,peak);c.lineTo(x+step*.5,y+h*.02);c.lineTo(x+step,y-h*(.04+hash(i+2+chapter*31)*.08));
  }
  c.lineTo(w,h);c.closePath();c.fillStyle=color;c.fill();
  // atmospheric lower slope
  c.globalAlpha=.14;c.fillStyle='#f2be9e';c.fillRect(0,y-h*.018,w,h*.06);c.globalAlpha=1;
}
function drawPines(c,w,h,t,cam,chapter){
  const spacing=88*(h/800), offset=(cam*.18)%spacing, base=h*.79;
  for(let i=-1;i<w/spacing+2;i++){
    const worldIndex=Math.floor(cam*.18/spacing)+i;
    if(hash(worldIndex+100)<.32)continue;
    const x=i*spacing-offset, ht=(52+hash(worldIndex+151)*90)*(h/800), width=ht*.43;
    c.globalAlpha=.42+hash(worldIndex+13)*.28;c.fillStyle=chapter===2?'#292d4c':chapter===1?'#233a35':'#39443e';
    c.beginPath();c.moveTo(x,base-ht);c.lineTo(x-width,base-ht*.42);c.lineTo(x-width*.48,base-ht*.42);c.lineTo(x-width*1.2,base-ht*.05);c.lineTo(x+width*1.2,base-ht*.05);c.lineTo(x+width*.48,base-ht*.42);c.lineTo(x+width,base-ht*.42);c.closePath();c.fill();
  }
  c.globalAlpha=1;
}
function drawLand(c,w,h,t,cam,chapter,ground){
  const gr=c.createLinearGradient(0,ground-20,0,h);
  gr.addColorStop(0,chapter===2?'#45435b':chapter===1?'#384539':'#62513f');
  gr.addColorStop(.18,chapter===2?'#39394e':chapter===1?'#303a32':'#514535');
  gr.addColorStop(1,chapter===2?'#282b40':chapter===1?'#222d29':'#36332d');
  c.fillStyle=gr;c.beginPath();c.moveTo(0,ground);
  for(let x=0;x<=w+10;x+=12)c.lineTo(x,ground+Math.sin((x+cam*.23)*.008)*7+Math.sin((x+cam*.12)*.022)*2);
  c.lineTo(w,h);c.lineTo(0,h);c.closePath();c.fill();
  // distant bands in the earth
  for(let i=0;i<5;i++){
    c.globalAlpha=.025;c.fillStyle=i%2?'#efc998':'#11151b';
    c.fillRect(0,ground+40+i*48+Math.sin(t*.0003+i)*3,w,2);
  }
  c.globalAlpha=1;
}
function drawPath(c,w,h,t,cam,chapter,ground){
  const y=ground+24;
  c.save();c.globalAlpha=.26;c.fillStyle=chapter===2?'#b8a0a4':'#c49b71';
  c.beginPath();c.moveTo(w*.44,y-4);
  c.bezierCurveTo(w*.38,y+36,w*.54,h+30,w*.51,h+45);
  c.lineTo(w*.78,h+45);c.bezierCurveTo(w*.62,y+44,w*.67,y+15,w*.58,y-4);c.closePath();c.fill();
  c.globalAlpha=.09;c.fillStyle='#f8d5a5';c.beginPath();c.ellipse(w*.53,y+95,w*.12,5,0,0,Math.PI*2);c.fill();c.restore();
}

